package dev.horizonlab.parity;
import com.google.gson.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import net.minecraft.core.component.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.item.enchantment.*;
/** Native Inventory storage/selection with real stack/component and equipment aliases. */
@SuppressWarnings({"unchecked","rawtypes"})
public final class VanillaPlayerInventoryOracle {
 static Item[] items;static DataComponentType[] keys;static Field components,count,patchMap,equipmentItems,changed;static Object removed;static ItemEnchantments enchanted;
 static EquipmentSlot[] mapped={EquipmentSlot.FEET,EquipmentSlot.LEGS,EquipmentSlot.CHEST,EquipmentSlot.HEAD,EquipmentSlot.OFFHAND,EquipmentSlot.BODY,EquipmentSlot.SADDLE};
 static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
 static int n(JsonObject o,String k){return o.get(k).getAsInt();}
 static int key(Object k){for(int i=0;i<keys.length;i++)if(keys[i]==k)return i;throw new AssertionError();}
 static int item(Item i){for(int k=0;k<items.length;k++)if(items[k]==i)return k;throw new AssertionError();}
 static Object value(int k,JsonElement v){if(v.isJsonNull())return null;int n=v.getAsInt();return switch(k){case 3->net.minecraft.util.Unit.INSTANCE;case 4->n==0?ItemEnchantments.EMPTY:enchanted;case 5->net.minecraft.network.chat.Component.literal(Integer.toString(n));default->n;};}
 static String text(int k,Object v){if(v==null||v==removed)return "none";return switch(k){case 3->"0";case 4->((ItemEnchantments)v).isEmpty()?"0":"1";case 5->((net.minecraft.network.chat.Component)v).getString();default->v.toString();};}
 static DataComponentMap prototype(JsonArray a){var b=DataComponentMap.builder();for(var e:a){var p=e.getAsJsonArray();int k=p.get(0).getAsInt();b.set(keys[k],value(k,p.get(1)));}return b.build();}
 static DataComponentPatch patch(JsonArray a){var b=DataComponentPatch.builder();for(var e:a){var p=e.getAsJsonArray();int k=p.get(0).getAsInt();if(p.get(1).isJsonNull())b.remove(keys[k]);else b.set(keys[k],value(k,p.get(1)));}return b.build();}
 static final class Data {
  PrintWriter out;ItemStack[] refs;Inventory[] inv;EntityEquipment[] equipment;IdentityHashMap<ItemStack,Integer> ids=new IdentityHashMap<>();
  int id(ItemStack s){return ids.computeIfAbsent(s,k->ids.size());}
  String snapshot(ItemStack s){try{var raw=(PatchedDataComponentMap)components.get(s);var p=new StringJoiner(",");for(var e:((Map<?,?>)patchMap.get(raw.asPatch())).entrySet())p.add(key(e.getKey())+"="+text(key(e.getKey()),e.getValue()));var v=new StringJoiner(",");for(int k=0;k<keys.length;k++)v.add(text(k,s.get(keys[k])));return id(s)+":"+item(s.getItem())+":"+count.getInt(s)+":"+s.getCount()+":"+s.getPopTime()+":"+s.isEmpty()+":"+s.isDamaged()+":"+s.isEnchanted()+":"+v+":"+p;}catch(Exception e){throw new AssertionError(e);}}
  void all()throws Exception {
   for(int i=0;i<refs.length;i++)out.println("ref "+i+" "+snapshot(refs[i]));
   for(int i=0;i<2;i++){var c=inv[i];out.println("inventory "+i+" "+c.getSelectedSlot()+" "+c.getTimesChanged()+" "+c.getFreeSlot()+" "+c.getSuitableHotbarSlot()+" "+c.isEmpty()+" "+c.countItem(items[0])+" "+c.countItem(items[1])+" "+c.countItem(items[2]));var slots=new StringJoiner(" | ");for(int j=0;j<43;j++)slots.add(snapshot(c.getItem(j)));out.println("slots "+slots);var eq=new StringJoiner(" | ");for(var e:((EnumMap<EquipmentSlot,ItemStack>)equipmentItems.get(equipment[i])).entrySet())eq.add(e.getKey().name()+"="+snapshot(e.getValue()));out.println("equipment "+eq);for(int j=0;j<refs.length;j++)out.println("query "+j+" "+c.contains(refs[j])+" "+c.findSlotMatchingItem(refs[j])+" "+c.findSlotMatchingCraftingIngredient(items[1].builtInRegistryHolder(),refs[j]));}
   out.println("empty "+snapshot(ItemStack.EMPTY));
  }
 }
 public static void main(String[] args)throws Exception {
  net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var lookup=net.minecraft.data.registries.VanillaRegistries.createWorldLookup();var m=new ItemEnchantments.Mutable(ItemEnchantments.EMPTY);m.set(lookup.lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(Enchantments.UNBREAKING),1);enchanted=m.toImmutable();
  items=new Item[]{Items.AIR,Items.STICK,Items.SHIELD};keys=new DataComponentType[]{DataComponents.MAX_STACK_SIZE,DataComponents.DAMAGE,DataComponents.MAX_DAMAGE,DataComponents.UNBREAKABLE,DataComponents.ENCHANTMENTS,DataComponents.CUSTOM_NAME};components=field(ItemStack.class,"components");count=field(ItemStack.class,"count");patchMap=field(DataComponentPatch.class,"map");removed=field(Class.forName("net.minecraft.core.component.Removed"),"INSTANCE").get(null);equipmentItems=field(EntityEquipment.class,"items");changed=field(Inventory.class,"timesChanged");Path dir=Path.of(args[1]);
  try(var out=new PrintWriter(Files.newBufferedWriter(dir.resolve(args[0]+".txt")));var lines=Files.lines(dir.resolve("inputs.txt"))){for(var line:(Iterable<String>)lines::iterator){var f=JsonParser.parseString(line).getAsJsonObject();for(int i=0;i<3;i++)items[i].builtInRegistryHolder().bindComponents(prototype(f.getAsJsonArray("prototypes").get(i).getAsJsonArray()));Inventory.EQUIPMENT_SLOT_MAPPING.clear();for(var e:f.getAsJsonArray("equipment_order")){int i=e.getAsInt();Inventory.EQUIPMENT_SLOT_MAPPING.put(36+i,mapped[i]);}ItemStack.EMPTY.setCount(0);ItemStack.EMPTY.setPopTime(0);((PatchedDataComponentMap)components.get(ItemStack.EMPTY)).clearPatch();var d=new Data();d.out=out;d.ids.put(ItemStack.EMPTY,0);d.refs=new ItemStack[4];for(int i=0;i<4;i++){var v=f.getAsJsonArray("stacks").get(i).getAsJsonObject();int type=n(v,"item");d.refs[i]=type<0?ItemStack.EMPTY:new ItemStack(items[type],n(v,"count"));if(type>=0){d.refs[i].setPopTime(n(v,"pop"));((PatchedDataComponentMap)components.get(d.refs[i])).restorePatch(patch(v.getAsJsonArray("patch")));}}
   d.equipment=new EntityEquipment[]{new EntityEquipment(),new EntityEquipment()};if(f.get("shared_equipment").getAsBoolean())d.equipment[1]=d.equipment[0];d.inv=new Inventory[]{new Inventory(null,d.equipment[0]),new Inventory(null,d.equipment[1])};
   for(int i=0;i<2;i++){var initial=f.getAsJsonArray("inventories").get(i).getAsJsonObject();d.inv[i].setSelectedSlot(n(initial,"selected"));changed.setInt(d.inv[i],n(initial,"changed"));for(var entry:initial.getAsJsonArray("slots")){var pair=entry.getAsJsonArray();d.inv[i].setItem(pair.get(0).getAsInt(),d.refs[pair.get(1).getAsInt()]);}if(n(initial,"mainhand")>=0)d.equipment[i].set(EquipmentSlot.MAINHAND,d.refs[n(initial,"mainhand")]);}
   d.all();for(var ov:f.getAsJsonArray("ops")){var op=ov.getAsJsonObject();var c=d.inv[n(op,"inventory")];int a=n(op,"a"),b=n(op,"b"),slot=n(op,"slot"),amount=n(op,"amount");try{switch(op.get("kind").getAsString()){
    case "get":d.refs[b]=c.getItem(slot);break;case "set":c.setItem(slot,d.refs[a]);break;case "remove":d.refs[b]=c.removeItem(slot,amount);break;case "no-update":d.refs[b]=c.removeItemNoUpdate(slot);break;case "remove-ref":c.removeItem(d.refs[a]);break;case "select":c.setSelectedSlot(slot);break;case "selected":d.refs[b]=c.getSelectedItem();break;case "set-selected":d.refs[b]=c.setSelectedItem(d.refs[a]);break;case "remove-selected":d.refs[b]=c.removeFromSelected(op.get("all").getAsBoolean());break;case "pick":c.pickSlot(slot);break;case "add-pick":c.addAndPickItem(d.refs[a]);break;case "clear":c.clearContent();break;case "changed":c.setChanged();break;case "replace":c.replaceWith(d.inv[n(op,"other")]);break;case "equip":d.refs[b]=d.equipment[n(op,"inventory")].set(EquipmentSlot.values()[n(op,"equipment")],d.refs[a]);break;case "get-equip":d.refs[b]=d.equipment[n(op,"inventory")].get(EquipmentSlot.values()[n(op,"equipment")]);break;case "alias":d.refs[b]=d.refs[a];break;case "copy":d.refs[b]=d.refs[a].copy();break;case "count":d.refs[a].setCount(amount);break;case "component":int k=n(op,"key");d.refs[a].set(keys[k],value(k,op.get("value")));break;default:throw new AssertionError();}out.println("result ok");}catch(IndexOutOfBoundsException|IllegalArgumentException|NullPointerException e){out.println("result error");}d.all();}
  }}
 }
}
